contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public payable {
        require(dummy >= 0);
        uint256 recordedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(recordedBefore == 0);
        require(address(c).balance == 0);
        c.withdraw(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == 0 && address(c).balance == 0);
    }
    receive() external payable {}
}

