pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy >= 0);
        uint256 recordedBefore;
        try c.balances(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        vm.assume(recordedBefore == 0);
        vm.assume(address(c).balance == 0);
        try c.withdraw() {} catch { return; }
        assertTrue(c.balances(address(this)) == 0 && address(c).balance == 0);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
